o barcode claim, hosted loading not yet proven"}],"review_status":"approved","reviewed_at":"2026-11-03T17:38:12.630Z","review_batch":"nl-continuation-20261103-001"}},{"ref":"w227","relation":"works","key":{"native_identity_key":"nlcontinuation:20261103:ol:OL24348719W"},"before":null,"after":{"title":"De moord op Anna Bentveld","author_id":3405,"first_publish_year":1967,"open_library_id":"OL24348719W","cover_id":null,"source_type":"open_library","work_type":"novel","native_identity_key":"nlcontinuation:20261103:ol:OL24348719W"}},{"ref":"e227","relation":"editions","key":{"open_library_edition_id":"OL32241443M"},"before":null,"after":{"work_id":"@w227","open_library_edition_id":"OL32241443M","isbn_10":"9026101376","isbn_13":"9789026101373","language":"dut","publisher":"Fontein","title":"De Cock en de moord op Anna Bentveld"}},{"ref":"d227","relation":"catalog_work_descriptions","key":{"work_id":"@w227","language":"nl"},"before":null,"after":{"work_id":"@w227","language":"nl","bound_author_id":3405,"text":"Anna Bentveld wordt dood aangetroffen in haar woning aan een Amsterdamse gracht. Ook een tas met veel geld is verdwenen. Rechercheur Peeters onderzoekt de moord en de contacten die Anna als prostituee heeft gehad. Een jonge inbreker komt in beeld en bekent na een hard verhoor, maar Peeters is niet overtuigd dat daarmee de waarheid vaststaat. Hij probeert de aanwijzingen opnieuw te wegen. De Cock verschijnt hier vooral als steun voor zijn collega, die een haastige conclusie wil voorkomen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.bruna.nl/ebooks/de-cock-en-de-moord-op-anna-bentveld-deel-4-9789026124549","evidence":[{"type":"exact_edition_and_work_identity","reference":"reviewed-227.json","sources":[{"url":"https://www.bruna.nl/ebooks/de-cock-en-de-moord-op-anna-bentveld-deel-4-9789026124549","role":"Publisher-attributed substantial Peeters/Pepi narrative; ebook used only for content","checkedOn