6181955W"},"before":null,"after":{"title":"De vuurtoren","author_id":670,"first_publish_year":2010,"open_library_id":"OL26181955W","cover_id":null,"source_type":"open_library","work_type":"novel","native_identity_key":"nlcontinuation:20261103:ol:OL26181955W"}},{"ref":"e234","relation":"editions","key":{"open_library_edition_id":"OL35331713M"},"before":null,"after":{"work_id":"@w234","open_library_edition_id":"OL35331713M","isbn_10":"9046807185","isbn_13":"9789046807187","language":"dut","publisher":"Nieuw Amsterdam","title":"De vuurtoren"}},{"ref":"d234","relation":"catalog_work_descriptions","key":{"work_id":"@w234","language":"nl"},"before":null,"after":{"work_id":"@w234","language":"nl","bound_author_id":670,"text":"Na haar huwelijk met Lars raakt Leonie Reders hem plotseling kwijt: de natuurkundig ingenieur is spoorloos verdwenen. Ze probeert samen met haar vader Job te achterhalen waar hij is en wat hem is overkomen. Mensen die iets zouden kunnen vertellen, worden echter vermoord. De zoektocht grijpt Leonie persoonlijk aan en laat haar heen en weer bewegen tussen wanhoop en vastberadenheid. Vader en dochter onderzoeken welke gebeurtenissen uit het verleden achter de verdwijning kunnen zitten, terwijl nieuwe aanwijzingen steeds gevaarlijker blijken.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.lannoo.com/nl-nl/literatuur-romans/de-vuurtoren-9789046808702","evidence":[{"type":"exact_edition_and_work_identity","reference":"reviewed-234.json","sources":[{"url":"https://www.lannoo.com/nl-nl/literatuur-romans/de-vuurtoren-9789046808702","role":"Primary publisher Jan/Sanne credit and Lars disappearance/informants killed premise; ebook not proposed print","checkedOn":"2026-11-03"},{"url":"https://data.bibliotheken.nl/id/nbt/p322923042","role":"Exact selected Dutch paperback identity and expanded author name","checkedOn":"2026-11-03"},{"url":"https://boekenbalie.nl/de-vuurtoren-reders-reders-5/9789046807187","role":"Exact selected printed ISBN, imprint and joint-author front","checkedOn":"2026-11-03"}],"decision":"Existing JanTerlouw authority670 reused, with Sanne explicitly retained as coauthor in provenance. Current same-author six Works compared, no DeVuurtoren match. Source KB expanded JanCornelisTerlouw resolves alias; combined source author display is not another person. Ebook publisher source supplies story only, selected2010 paperback stays9789046807187.","additionalCredits":[{"name":"Sanne Terlouw","sourceAuthorKey":"OL5152952A","role":"coauthor"}]},{"type":"original_substantive_source_review","source":"https://www.lannoo.com/nl-nl/literatuur-romans/de-vuurtoren-9789046808702","provenance":"original_source_reviewed_summary","reference":null},{"type":"exact_edition_front_review","receipt":"cover-12150955.json","sha256":"38a5df482c7e6b07a98d1ac4a85b93842082c5d7b3063233fe774ba3e2a60886","bytes":566270,"review":"Decoded orange sunset sea front: Jan & Sanne Terlouw, De vuurtoren, NwAdam. Exact source ISBN; library barcode top corner and566270B limitation retained.","limitation":"Front/source binding; no barcode claim, hosted loading not yet proven"}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-03T17:38:12.630Z","review_batch":"nl-continuation-20261103-001"}},{"ref":"m234","relation":"catalog_edition_metadata","key":{"edition_id":"@e234"},"before":null,"after":{"edition_id":"@e234","work_id":"@w234","bound_author_id":670,"bound_title":"De vuurtoren","bound_language":"dut","bound_isbn13":"9789046807187","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/12150955-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/12150955-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p322923042","evidence":[{"type":"exact_edition_and_work_identity","reference":"reviewed-234.json","sources":[{"url":"https://www.lannoo.com/nl-nl/literatuur-romans/de-vuurtoren-9789046808702","role":"Primary publisher Jan/Sanne credit and Lars disappearance/informants killed premise; ebook not proposed print","checkedOn":"2026-11-03"},{"url":"https://data.bibliotheken.nl/id/nbt/p322923042","role":"Exact selected Dutch paperback identity and expanded author name","checkedOn":"2026-11-03"},{"url":"https://boekenbalie.nl/de-vuurtoren-reders-reders-5/9789046807187","role":"Exact selected printed ISBN, imprint and joint-author front","checkedOn":"2026-11-03"}],"decision":"Existing JanTerlouw authority670 reused, with Sanne explicitly retained as coauthor in provenance. Current same-author six Works compared, no DeVuurtoren match. Source KB expanded JanCornelisTerlouw resolves alias; combined source author display is not another person. Ebook publisher source supplies story only, selected2010 paperback stays9789046807187.","additionalCredits":[{"name":"Sanne Terlouw","sourceAuthorKey":"OL5152952A","role":"coauthor"}]},{"type":"original_substantive_source_review","source":"https://www.lannoo.com/nl-nl/literatuur-romans/de-vuurtoren-9789046808702","provenance":"original_source_reviewed_summary","reference":null},{"type":"exact_edition_front_review","receipt":"cover-12150955.json","sha256":"38a5df482c7e6b07a98d1ac4a85b93842082c5d7b3063233fe774ba3e2a60886","bytes":566270,"review":"Decoded orange sunset sea front: Jan & Sanne Terlouw, De vuurtoren, NwAdam. Exact source ISBN; library barcode top corner and566270B limitation retained.","limitation":"Front/source binding; no barcode claim, hosted loading not yet proven"}],"review_status":"approved","reviewed_at":"2026-11-03T17:38:12.630Z","review_batch":"nl-continuation-20261103-001"}},{"ref":"w236","relation":"works","key":{"native_identity_key":"nlcontinuation:20261103:ol:OL27060702W"},"before":null,"after":{"title":"Venijn","author_id":670,"first_publish_year":2007,"open_library_id":"OL27060702W","cover_id":null,"source_type":"open_library","work_type":"novel","native_identity_key":"nlcontinuation:20261103:ol:OL27060702W"}},{"ref":"e236","relation":"editions","key":{"open_library_edition_id":"OL36693487M"},"before":null,"after":{"work_id":"@w236","open_library_edition_id":"OL36693487M","isbn_10":"9046802086","isbn_13":"9789046802083","language":"dut","publisher":"Nieuw Amsterdam","title":"Venijn"}},{"ref":"d236","relation":"catalog_work_descriptions","key":{"work_id":"@w236","language":"nl"},"before":null,"after":{"work_id":"@w236","language":"nl","bound_author_id":670,"text":"Job Reders komt vrij nadat hij zeven jaar onschuldig heeft vastgezeten voor de moord op zijn oom Bart. Met zijn dochter Leonie, die hij nauwelijks kent, probeert hij te achterhalen wie werkelijk verantwoordelijk is. Hun onderzoek voert hen langs de zakelijke en persoonlijke contacten van de vermoorde man. Terwijl vader en dochter elkaar opnieuw leren kennen, ontdekken zij hoe lastig het is betrouwbare verklaringen te krijgen. De zoektocht wordt gevaarlijk wanneer ook iemand uit hun eigen omgeving wordt getroffen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://rozet.nl/catalogus/752938/","evidence":[{"type":"exact_edition_and_work_identity","reference":"reviewed-236.json","sources":[{"url":"https://rozet.nl/catalogus/752938/","role":"Library detailed father/daughter investigation, joint credit and first2007; reviewed reprint2009 is not selected ISBN","checkedOn":"2026-11-03"},{"url":"https://data.bibliotheken.nl/id/nbt/p30304148X","role":"Exact Dutch2007 selected paperback and author authority","checkedOn":"2026-11-03"},{"url":"https://openlibrary.org/books/OL36693487M","role":"Pinned exact Dutch printed edition, joint byline and publisher","checkedOn":"2026-11-03"}],"decision":"Distinct Reders&Reders novel2, not DeVuurtoren/other Terlouw title. JanCornelis alias resolves author670, Sanne coauthor retained. Rozet2009 reprint used for content/joint credit and explicit first2007, not substituted for selected2007ISBN978904